package Renderer;
use strict;
use warnings;
use Exporter 'import';
our @EXPORT_OK = qw(render);

# Render a comment into HTML.
sub render {
    my ($text) = @_;
    return "<div class='comment'>" . $text . "</div>";
}

1;

use strict;
use warnings;
use Test::More;
use Renderer qw(render);

subtest wraps_comment => sub {
    is(render('hello'), "<div class='comment'>hello</div>", 'wrapped');
};

done_testing;
